// Normalises a fee / payment event so this workflow can be executed on its own.
// Accepts: foi-fee-payment / foi-manage-payment items from FOI Request Routing (normalised fields +
// `payload` + `metadata`), the snake_case inputs sent by the IAO sub-workflows (feeAction initiate/cancel),
// and foi-payment-expired items from FOI Payment Expiry SLA Job.
// Replaces the old Wait-based model: each outcome (PAID / CANCELLED / EXPIRED) is its own execution.
try {

const src = $input.first().json || {};

const parseJson = (value) => {
  if (value && typeof value === 'object') return value;
  if (typeof value === 'string' && value.trim()) {
    try { return JSON.parse(value); } catch (e) {
      try { return JSON.parse(value.replace(/'/g, '"')); } catch (e2) { return {}; }
    }
  }
  return {};
};
const first = (...values) => {
  for (const v of values) { if (v !== undefined && v !== null && v !== '') return v; }
  return null;
};
// const str = (v) => (v === undefined || v === null ? '' : String(v));
const str = (v) =>
  v === undefined || v === null
    ? ''
    : typeof v === 'object'
      ? JSON.stringify(v)
      : typeof v === 'string'
        ? v
        : String(v);

const bool = (v) => v === true || (typeof v === 'string' && v.trim().toLowerCase() === 'true');

const metadata = parseJson(src.metadata);
const foiRequestMetaData = parseJson(metadata?.foiRequestMetaData);
const event = str(src.event);
const eventId = str(src.eventId);
const occurredAt = str(src.occurredAt);
const status = str(first(src?.status, metadata?.status));
const category = str(src.category);
const paymentStatus = str(first(src.paymentStatus, metadata?.paymentstatus)).toUpperCase();

let feeAction = str(src.feeAction);
if (!feeAction) {
  if (event === 'foi-fee-payment' || category === 'foi-fee-payment') {
    feeAction = 'initiate';
  } else if (event === 'foi-payment-expired') {
    feeAction = 'expire';
  } else if (event === 'foi-manage-payment' || category === 'foi-manage-payment') {
    feeAction = paymentStatus === 'PAID' ? 'paid' : (paymentStatus === 'CANCELLED' ? 'cancel' : (paymentStatus === 'EXPIRED' ? 'expire' : 'unsupported'));
  } else {
    feeAction = 'unsupported';
  }
}

const fileNumber = str(src.fileNumber);
const applicantCorrespondenceId = str(first(src.applicantCorrespondenceId, foiRequestMetaData?.applicantcorrespondenceid, metadata?.applicantCorrespondenceId));
const templateName = str(first(src.templateName, foiRequestMetaData?.templatename, metadata?.templateName));
const paymentExpiryDate = str(first(src.paymentExpiryDate, foiRequestMetaData?.paymentExpiryDate));

return [{
  json: {
    event,
    eventId,
    occurredAt,
    feeAction,
    category,
    applicantCorrespondenceId,
    templateName,
    paymentStatus: paymentStatus,
    isOfflinePayment: bool(src.isOfflinePayment),
    isSync: bool(src.isSync),
    isPaymentActive: bool(src.isPaymentActive),
    rawRequestId: str(first(src.rawRequestId,metadata?.rawRequestId)),
    foiRequestId: str(src.foiRequestId),
    ministryRequestId: str(src.ministryRequestId),
    serviceKey: str(src?.serviceKey),
    paymentExpiryDate,
    status,
    previousStatus: str(src.previousStatus),
    nextStateName: str(foiRequestMetaData?.nextStateName),
    fileNumber: fileNumber,
    triggeredBy: str(first(src.triggeredBy, src?.event)),
    metadata: str(metadata),
    executionId: $execution.id
  }
}];

} catch (error) {
  const src = $input.first().json || {};
    return {
      json: {
        event: '',
        eventId: (src && typeof src === 'object' && typeof src.eventId === 'string') ? src.eventId : null,
        receivedEvent: (src && typeof src === 'object' && typeof src.event === 'string') ? src.event : null,
        error: true,
        errorMessage: error.message,
        metadata: src.metadata ?? null,
        executionId: $execution.id,
      },
    };
}

// Only what this workflow needs: the online payment gate and the payment form type.
// The API fills in the submission itself (FOI Backend API Manager, foipayment-formsubmission-create).
try {
  const resp = $json.body;
  const balanceDueRaw = (resp.cfrfee && resp.cfrfee.feedata) ? resp.cfrfee.feedata.balanceDue : undefined;

  const previousStatus = $('Set Event Variables').item.json.previousStatus;
  const templateName = $('Set Event Variables').item.json.templateName;
  const formType = (previousStatus === 'Response' || (templateName && templateName.toLowerCase() === 'payoutstanding'))
    ? 'payoutstanding'
    : 'payonline';

  return {
    json: {
      fee: parseFloat(balanceDueRaw),
      hasEmail: resp.hasEmail === true,
      isOfflinePayment: resp.isofflinepayment,
      formType
    }
  };
} catch (error) {
  const input = $('Set Event Variables').first().json || {};
    return {
      json: {
        event: '',
        receivedEvent: (input && typeof input === 'object' && typeof input.event === 'string') ? input.event : null,
        error: true,
        errorMessage: error.message,
        metadata: input.metadata ?? null,
        executionId: $execution.id,
      },
    };
}

// G12: plans the PENDING payment SLA row for an initiation, before anything is created in Form.io.
// At most one non-terminal (PENDING or ACTIVE) row exists per ministry request: it is reused, never duplicated.
// A PENDING row left by an earlier run of the SAME initiation (same correspondence, template and expiry date) keeps
// its Form.io ids, so a replay does not create a second submission. A different initiation, or an ACTIVE row that a
// new initiation supersedes, starts a fresh submission on the same row.
const rows = $input.all()
  .map((item) => item.json)
  .filter((row) => row && row.id !== undefined && row.id !== null && row.id !== '');
const vars = $('Set Event Variables').first().json;

const clean = (value) => {
  const text = String(value ?? '').trim();
  return text === 'undefined' || text === 'null' ? '' : text;
};
const newestFirst = (a, b) => {
  const byCreated = String(b.createdAt ?? '').localeCompare(String(a.createdAt ?? ''));
  return byCreated !== 0 ? byCreated : Number(b.id) - Number(a.id);
};

const open = rows.filter((row) => row.sla_status === 'PENDING' || row.sla_status === 'ACTIVE').sort(newestFirst);
const current = open[0] || null;

const sameInitiation = Boolean(current)
  && current.sla_status === 'PENDING'
  && clean(current.applicant_correspondence_id) === clean(vars.applicantCorrespondenceId)
  && clean(current.template_name) === clean(vars.templateName)
  && clean(current.payment_expiry_date) === clean(vars.paymentExpiryDate);
const reuseIds = sameInitiation && ['form_id', 'submission_id', 'payment_url'].every((name) => Boolean(clean(current[name])));

const serviceKey = vars.serviceKey === 'correspondence'
  ? 'correspondence'
  : (vars.previousStatus === 'Response' ? 'payoutstanding' : 'payonline');

return [{
  json: {
    openRowId: current ? current.id : null,
    openStatus: current ? current.sla_status : '',
    duplicateOpenIds: open.slice(1).map((row) => row.id),
    reuseIds,
    formId: reuseIds ? clean(current.form_id) : '',
    submissionId: reuseIds ? clean(current.submission_id) : '',
    paymentUrl: reuseIds ? clean(current.payment_url) : '',
    slaType: 'payment-expiry',
    foiRequestId: String(vars.foiRequestId || ''),
    ministryRequestId: String(vars.ministryRequestId || ''),
    fileNumber: String(vars.fileNumber || ''),
    serviceKey,
    templateName: String(vars.templateName || ''),
    previousStatus: String(vars.previousStatus || ''),
    nextStateName: String(vars.nextStateName || ''),
    applicantCorrespondenceId: String(vars.applicantCorrespondenceId || ''),
    paymentExpiryDate: String(vars.paymentExpiryDate || ''),
    metadata: vars.metadata
  },
  pairedItem: { item: 0 }
}];

// Both the insert and the update branch end here: take the id of the PENDING row that was written.
const plan = $('Plan Payment SLA').first().json;
const written = $input.first().json || {};
const slaId = written.id ?? plan.openRowId;
if (slaId === undefined || slaId === null || slaId === '') {
  throw new Error('The PENDING payment SLA row was not written (no row id returned).');
}
return [{ json: { ...plan, slaId }, pairedItem: { item: 0 } }];

// The payment URL comes from the API (new submission) or from the PENDING SLA row (replay).
// No try/catch on purpose: a missing value must fail the run, so an empty payment URL is never saved or emailed.
const missing = ['formId', 'submissionId', 'paymentUrl'].filter((name) => !$json[name]);
if (missing.length) {
  throw new Error('The payment form submission is incomplete (missing ' + missing.join(', ') + ') for ministry request ' + $('Set Event Variables').item.json.ministryRequestId + '.');
}

return {
  json: {
    ...$json,
    saveDataPayload: JSON.stringify({
      paymenturl: $json.paymentUrl,
      paymentexpirydate: $('Set Event Variables').item.json.paymentExpiryDate
    })
  }
};

// Replaces the 20-day 'Wait Payment Outcome' timeout with an SLA row that FOI Payment Expiry SLA Job checks.
// Expiry = end of the payment expiry date sent with the fee event, in UTC (Camunda runs with TZ=UTC); if no
// valid date was sent, the previous 20-day wait is used.
try {
  const vars = $('Set Event Variables').first().json;
  const save = $('Build Save Payload').first().json;
  const notify = $('Set Notify Payment Vars').first().json;
  const PAYMENT_WAIT_DAYS = 20;

  let expiresAt = null;
  let expirySource = 'payment_expiry_date';
  const raw = String(vars.paymentExpiryDate || '').trim();
  if (raw) {
    const parsed = DateTime.fromISO(raw, { zone: 'utc' });
    if (parsed.isValid) expiresAt = raw.length <= 10 ? parsed.endOf('day') : parsed;
  }
  if (!expiresAt) {
    expiresAt = DateTime.utc().plus({ days: PAYMENT_WAIT_DAYS });
    expirySource = `default ${PAYMENT_WAIT_DAYS} days`;
  }

  return [{
    json: {
      slaType: 'payment-expiry',
      slaStatus: 'ACTIVE',
      foiRequestId: String(vars.foiRequestId || ''),
      ministryRequestId: String(vars.ministryRequestId || ''),
      fileNumber: String(vars.fileNumber || ''),
      serviceKey: String(notify.serviceKey || ''),
      templateName: String(vars.templateName || ''),
      previousStatus: String(vars.previousStatus || ''),
      nextStateName: String(vars.nextStateName || ''),
      applicantCorrespondenceId: String(vars.applicantCorrespondenceId || ''),
      paymentStatus: String(vars.paymentStatus || 'NOT PAID'),
      paymentUrl: String(save.paymentUrl || ''),
      formId: String(save.formId || ''),
      submissionId: String(save.submissionId || ''),
      paymentExpiryDate: raw,
      expiresAt: expiresAt.toUTC().toISO(),
      expirySource,
      metadata: vars.metadata
    }
  }];

} catch (error) {
  const input = $('Set Event Variables').first().json;
  return {
    json: {
      event: '',
      receivedEvent: (input && typeof input === 'object' && typeof input.event === 'string') ? input.event : null,
      error: true,
      errorMessage: error.message,
      metadata: input.metadata ?? null,
      executionId: $execution.id,
    },
  };
}
